(() => {
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const finePointer = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  // Real QR matrices in the hero cards, generated by the same encoder as the tool.
  document.querySelectorAll('.art-pattern[data-qr]').forEach((node, index) => {
    try {
      const qr = QRLib.encode(node.dataset.qr, 'M');
      const n = qr.size, quiet = 4, size = n + quiet * 2;
      let path = '';
      for (let y=0;y<n;y++) for (let x=0;x<n;x++) if(qr.modules[y][x]) path += `M${x+quiet},${y+quiet}h1v1h-1z`;
      node.innerHTML = `<svg viewBox="0 0 ${size} ${size}" role="img" aria-label="Przykładowy kod QR"><rect width="${size}" height="${size}" fill="#fff"/><path d="${path}" fill="#15191f"/></svg>`;
    } catch (_) { node.textContent = ''; }
  });
  const card = document.querySelector('.card');
  const art = document.querySelector('.hero-art');
  if (!reduceMotion && finePointer && card) {
    card.addEventListener('pointermove', event => {
      const r = card.getBoundingClientRect(), x=(event.clientX-r.left)/r.width, y=(event.clientY-r.top)/r.height;
      card.style.transform = `perspective(1200px) rotateX(${(0.5-y)*1.1}deg) rotateY(${(x-0.5)*1.4}deg) translateY(-1px)`;
    });
    card.addEventListener('pointerleave', () => { card.style.transform = ''; });
  }
  if (!reduceMotion && finePointer && art) {
    art.addEventListener('pointermove', event => {
      const r=art.getBoundingClientRect(), x=(event.clientX-r.left)/r.width-.5, y=(event.clientY-r.top)/r.height-.5;
      const front=art.querySelector('.art-card-front'), back=art.querySelector('.art-card-back');
      if(front) front.style.transform=`rotate(6deg) translate3d(${x*5}px,${y*5}px,10px)`;
      if(back) back.style.transform=`rotate(-8deg) translate3d(${-x*4}px,${-y*4}px,-18px)`;
    });
    art.addEventListener('pointerleave',()=>{const f=art.querySelector('.art-card-front'),b=art.querySelector('.art-card-back');if(f)f.style.transform='';if(b)b.style.transform='';});
  }
  document.querySelectorAll('.qr-faq details').forEach(item => item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.qr-faq details[open]').forEach(other=>{if(other!==item)other.open=false;});}));
})();